package net.hivel.islandsrpg.boss;
import net.hivel.islandsrpg.IslandsRPGPlugin; import net.hivel.islandsrpg.util.ColorUtil; import org.bukkit.Bukkit; import org.bukkit.boss.BossBar; import org.bukkit.entity.LivingEntity; import org.bukkit.entity.Player; import java.util.*;
public class BossBarService { private final IslandsRPGPlugin plugin; private final Map<UUID,BossBar> bars=new HashMap<>(); public BossBarService(IslandsRPGPlugin p){plugin=p;} public void create(LivingEntity e,BossDefinition d){if(!d.bossbarEnabled())return; BossBar b=Bukkit.createBossBar(ColorUtil.color(d.barTitle()),d.barColor(),d.barStyle()); bars.put(e.getUniqueId(),b); update(e,d);} public void update(LivingEntity e,BossDefinition d){BossBar b=bars.get(e.getUniqueId()); if(b==null)return; double hp=Math.max(0,e.getHealth()), max=d.health(); b.setProgress(Math.max(0,Math.min(1,hp/max))); b.setTitle(ColorUtil.color(d.barTitle().replace("%health%",String.valueOf((int)Math.ceil(hp))).replace("%max_health%",String.valueOf((int)Math.ceil(max))))); for(Player p:Bukkit.getOnlinePlayers()) if(p.getWorld().equals(e.getWorld())&&p.getLocation().distanceSquared(e.getLocation())<=d.barRange()*d.barRange()) b.addPlayer(p); else b.removePlayer(p);} public void remove(LivingEntity e){BossBar b=bars.remove(e.getUniqueId()); if(b!=null)b.removeAll();} public void removeAll(){bars.values().forEach(BossBar::removeAll); bars.clear();} }
